{/* ── 1. MASTER SUMMARY CARD (Unified Information Container) ──────── */}
<CollapsibleInfoGrid
  title={
    <div className="flex items-center gap-2 text-sm font-bold text-foreground uppercase tracking-wide">
      <span className="w-2.5 h-2.5 rounded-full bg-primary inline-block" />
      <span>
        {t('customsDeclaration:section.declarationInfo', {
          defaultValue: 'Thông tin Tờ khai Hải quan',
        })}
      </span>
    </div>
  }
  defaultExpanded={true}
  className="border shadow-xs rounded-xl"
  gridClassName="!block space-y-6"
>
  {/* Nhóm 1: Thông tin Tờ khai & Hải quan */}
  <div className="space-y-3">
    <div className="flex items-center gap-2 text-xs font-bold text-foreground uppercase tracking-wider">
      <span className="w-2 h-2 rounded-full bg-primary inline-block" />
      <span>
        {t('customsDeclaration:section.declarationSub', {
          defaultValue: 'Chi tiết Tờ khai & Hải quan',
        })}
      </span>
    </div>
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-x-6 gap-y-3 min-w-0">
      <InfoItem
        label={t('customsDeclaration:declarationNo', {
          defaultValue: 'Số Tờ khai chính thức',
        })}
        value={
          <span className="font-bold text-foreground">
            {declaration?.declarationNo ||
              t('customsDeclaration:unregistered', { defaultValue: 'Chưa đăng ký' })}
          </span>
        }
      />
      <InfoItem
        label={t('customsDeclaration:directionAndType', {
          defaultValue: 'Chiều & Loại hình Hải quan',
        })}
        value={
          <div className="flex items-center gap-2 flex-wrap">
            <span
              className={`text-xs font-semibold px-2 py-0.5 rounded ${declaration?.isExport ? 'bg-blue-50 text-blue-700 border border-blue-200' : 'bg-purple-50 text-purple-700 border border-purple-200'}`}
            >
              {declaration?.isExport
                ? t('customsDeclaration:export', { defaultValue: 'Xuất khẩu' })
                : t('customsDeclaration:import', { defaultValue: 'Nhập khẩu' })}
            </span>
            <span className="font-semibold text-foreground">
              {declaration?.declarationTypeCode
                ? `${declaration.declarationTypeCode} - ${declaration.declarationTypeNameSnapshot || ''}`
                : declaration?.declarationTypeNameSnapshot || '-'}
            </span>
          </div>
        }
      />
      <InfoItem
        label={t('customsDeclaration:registrationDate', {
          defaultValue: 'Ngày đăng ký tờ khai',
        })}
        value={
          declaration?.registrationDate
            ? new Date(declaration.registrationDate).toLocaleDateString('vi-VN')
            : '-'
        }
      />
      <InfoItem
        label={t('customsDeclaration:clearanceDate', { defaultValue: 'Ngày thông quan' })}
        value={
          declaration?.clearanceDate
            ? new Date(declaration.clearanceDate).toLocaleDateString('vi-VN')
            : '-'
        }
      />
      <InfoItem
        label={t('customsDeclaration:customsOffice', { defaultValue: 'Chi cục Hải quan' })}
        value={
          declaration?.customsOfficeCode
            ? `${declaration.customsOfficeCode} - ${declaration.customsOfficeName || ''}`
            : declaration?.customsOfficeName || '-'
        }
      />
      <InfoItem
        label={t('customsDeclaration:customsStorageCode', {
