import { LazyComboboxWithFilters } from '@shared/components/lazy-combobox-with-filters';
import { getEntityFilters } from '@shared/config/entity-filter-registry';
import type { ICustomsDeclarationDetail } from '@/types/customs-declaration.type';

interface CustomsDeclarationDetailTableProps {
  data?: ICustomsDeclarationDetail[];
  readOnly?: boolean;
  exchangeRate?: number;
}

interface DetailFilters {
  originCountry?: string;
  hsCode?: string;
}

export function CustomsDeclarationDetailTable({
  data,
  readOnly = false,
  exchangeRate = 1,
}: CustomsDeclarationDetailTableProps) {
  const { t } = useTranslation(['customsDeclaration', 'common', 'action']);
  const formContext = useFormContext();
  const fallbackForm = useForm();
  const control = formContext?.control ?? fallbackForm.control;
  const [searchText, setSearchText] = useState('');
  const [detailFilters, setDetailFilters] = useState<DetailFilters>({});

  // Fallback field array only when in edit mode
  const { fields, append, remove } = useFieldArray({
    control,
    name: 'details',
  });

  const register = formContext?.register ?? fallbackForm.register;
  const watch = formContext?.watch ?? fallbackForm.watch;
  const setValue = formContext?.setValue ?? fallbackForm.setValue;

