type OmittedProps = 'options' | 'loading' | 'onFilterChange' | 'extraFooter';

export type LazyComboboxWithFiltersProps = LazyComboboxWithFiltersOwnProps &
  Omit<ComboboxWithFiltersProps<unknown>, OmittedProps>;

/**
 * A Combobox with built-in lazy loading AND a filter popover.
 * It combines the automatic data fetching of LazyCombobox with the UI features of ComboboxWithFilters.
 */
export function LazyComboboxWithFilters({
  entityCode,
  baseExtraFilters = '',
  apiBasePath,
  enabled = true,
  extraKeys,
  sorts,
  filters,
  excludeValues,
  valueField = 'value',
  onSelectOption,
  onValueChange,
  onOpenChange,
  value,
  ...props
}: LazyComboboxWithFiltersProps) {
  const [filterValues, setFilterValues] = useState<FilterValues>({});

  // True lazy-on-open: don't fetch until the popover has been opened at least once.
  // Exception: if a value is already selected (e.g. editing an existing row), fetch anyway
  // so the selected option's label can be resolved without requiring the user to open it.
  const hasOpenedRef = useRef(false);
  const [hasOpened, setHasOpened] = useState(false);
  const hasValue = Array.isArray(value) ? value.length > 0 : !!value;

  const handleOpenChange = useCallback(
    (open: boolean, option?: any) => {
      if (open && !hasOpenedRef.current) {
        hasOpenedRef.current = true;
        setHasOpened(true);
      }
      onOpenChange?.(open, option);
    },
    [onOpenChange],
  );

  // Combine baseExtraFilters and filterValues into a single filter string
  const combinedFilters = useMemo(() => {
    const dynamicFilters = Object.entries(filterValues)
      .filter(([_, val]) => !!val)
      .map(([key, val]) => `${key}==${String(val)}`);

    if (!baseExtraFilters) return dynamicFilters.join(',');
    if (dynamicFilters.length === 0) return baseExtraFilters;
    return `${baseExtraFilters},${dynamicFilters.join(',')}`;
  }, [baseExtraFilters, filterValues]);

  const { options, isLoading, totalCount, loadedCount, error, refetch } = useMasterTableDropdown(
    entityCode,
    enabled && (hasOpened || hasValue),
    '',
    combinedFilters,
    apiBasePath,
    extraKeys,
    sorts,
  );

  const finalOptions = useMemo(() => {
    let opts = options;
    if (valueField === 'code') {
      opts = opts.map((opt: any) => ({
        ...opt,
        value: opt.code || opt.value,
      }));
    } else if (valueField === 'label' || valueField === 'name') {
      opts = opts.map((opt: any) => ({
        ...opt,
        value: opt.label || opt.value,
      }));
    }
    if (excludeValues && excludeValues.length > 0) {
      const excludeSet = new Set(excludeValues.filter(Boolean));
      opts = opts.filter((opt: any) => !excludeSet.has(opt.value));
    }
    return opts;
  }, [options, valueField, excludeValues]);

  // Wrap onValueChange to also support onSelectOption and forward snapshot
  const handleValueChange = useCallback(
    (
      value: string,
      snapshotName?: string,
      snapshotCode?: string,
      option?: any,
    ) => {
      onValueChange?.(value, snapshotName, snapshotCode);
      if (onSelectOption) {
        const selected = option ?? finalOptions.find((opt: any) => opt.value === value);
        onSelectOption(selected);
      }
    },
    [onValueChange, onSelectOption, finalOptions],
  );

