export function LazyComboboxWithFilters({
  entityCode,
  baseExtraFilters = '',
  apiBasePath,
  enabled = true,
  extraKeys,
  sorts,
  filters,
  excludeValues,
  onSelectOption,
  onValueChange,
  onOpenChange,
  value,
  ...props
}: LazyComboboxWithFiltersProps) {
  const [filterValues, setFilterValues] = useState<FilterValues>({});

